<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, post } from '../api'
import { useArena } from '../stores/arena'
import Avatar from '../components/Avatar.vue'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const route = useRoute(), store = useArena(), profile = ref(null), modal = ref(false), duration = ref('3d'), subjectId = ref('')
onMounted(async () => { try { profile.value = await api(`/users/${route.params.id}`) } catch (e) { store.toast(e.message, 'error') } })
const friendship = computed(() => profile.value?.friendship)
const canChallenge = computed(() => friendship.value?.status === 'ACCEPTED')
const challenges = computed(() => store.passes.filter(p => p.subject_id && profile.value?.common_subject_ids?.includes(p.subject_id)))
async function add() { await store.run(async () => { profile.value.friendship = await post(`/friends/${profile.value.id}`) }, 'Заявка отправлена') }
async function accept() { await store.run(async () => { await post(`/friendships/${friendship.value.id}/respond`, { approve: true }); profile.value = await api(`/users/${route.params.id}`) }, 'Вы теперь друзья') }
async function challenge() { await store.run(async () => { await post('/duels', { opponent_id: profile.value.id, duration: duration.value, subject_id: Number(subjectId.value) || null }); modal.value = false; await store.refreshStudent() }, 'Вызов отправлен!') }
const title = computed(() => profile.value?.rewards?.find(r => r.id === profile.value?.active_title_id))
const frame = computed(() => profile.value?.rewards?.find(r => r.id === profile.value?.active_frame_id))
const badges = computed(() => profile.value?.showcase?.map(id => profile.value.rewards.find(r => r.id === id)).filter(Boolean) || [])
</script>
<template><section v-if="profile" class="public-profile"><router-link to="/friends" class="back-link"><Icon name="arrow-left" :size="16" />К друзьям</router-link><article class="public-profile-card panel"><div class="public-profile-banner"><span class="cloud-shape cloud-one"></span><span class="cloud-shape cloud-two"></span><span class="banner-caption"><Icon name="sparkles" :size="14" /> УЧАСТНИК АРЕНЫ</span></div><div class="public-profile-content"><Avatar :user="{...profile, active_frame_id: frame?.id}" :size="96" :framed="Boolean(frame)" /><h2>{{ profile.display_name }}</h2><p>@{{ profile.username || 'участник арены' }}</p><span v-if="title" class="public-title"><Icon name="crown" :size="15" />{{ title.name }}</span><div class="public-wins"><Icon name="trophy" :size="17" /><strong>{{ profile.duel_wins }}</strong> побед в дуэлях</div><div class="profile-divider"></div><span class="eyebrow">ВИТРИНА ДОСТИЖЕНИЙ</span><div v-if="badges.length" class="showcase-row public-badges"><div v-for="reward in badges" :key="reward.id" class="achievement"><span class="achievement-icon achievement-badge"><Icon :name="reward.icon || 'award'" :size="18" /></span><span><strong>{{ reward.name }}</strong><small>Достижение</small></span></div></div><p v-else class="muted">Новые достижения уже на пути.</p><div class="profile-divider"></div><div class="public-actions"><button v-if="friendship?.status === 'PENDING' && friendship?.requester_id !== store.user.id" class="btn primary" @click="accept"><Icon name="check" :size="16" />Принять заявку</button><button v-else-if="!friendship" class="btn primary" @click="add"><Icon name="user-plus" :size="16" />Добавить в друзья</button><span v-else class="chip blue"><Icon name="heart" :size="15" />{{ friendship.status === 'ACCEPTED' ? 'Вы друзья' : 'Заявка отправлена' }}</span><button v-if="canChallenge" class="btn secondary" @click="modal = true"><Icon name="swords" :size="16" />Вызвать на дуэль</button></div></div></article><Modal v-if="modal" title="Дружеская дуэль" @close="modal = false"><div class="modal-form"><p class="muted">Соперник: <strong>{{ profile.display_name }}</strong></p><label class="field-label">Продолжительность<select v-model="duration"><option value="1d">1 день</option><option value="3d">3 дня</option><option value="7d">7 дней</option><option value="1m">1 месяц</option></select></label><label class="field-label">Дисциплина<select v-model="subjectId"><option value="">Общий зачёт</option><option v-for="subject in challenges" :key="subject.id" :value="String(subject.subject_id)">{{ subject.name }}</option></select></label><button class="btn primary modal-submit" @click="challenge"><Icon name="swords" :size="16" />Отправить вызов</button></div></Modal></section><div v-else class="center-state"><span class="spinner" /></div></template>
